//! Golden `.pcapng` fixtures, built packet by packet.
//!
//! The committed files under `tests/fixtures/` are generated by
//! `cargo run -p collector --example gen_fixtures`; the `fixtures_are_current`
//! test checks they still match this code byte for byte.

#![allow(dead_code)]

use std::borrow::Cow;
use std::net::Ipv4Addr;
use std::time::Duration;

use pcap_file::pcapng::blocks::enhanced_packet::EnhancedPacketBlock;
use pcap_file::pcapng::blocks::interface_description::{
    InterfaceDescriptionBlock, InterfaceDescriptionOption,
};
use pcap_file::pcapng::PcapNgWriter;
use pcap_file::DataLink;

/// Capture time of the first packet: 2027-01-15T08:00:00Z, on a window
/// boundary for any whole-second window.
pub const T0: u64 = 1_800_000_000 * SEC;
pub const SEC: u64 = 1_000_000_000;
pub const MS: u64 = 1_000_000;
/// The window length the golden outputs are produced with.
pub const WINDOW_NS: u64 = SEC;

pub const SYN: u8 = 0x02;
pub const ACK: u8 = 0x10;
pub const PSH: u8 = 0x08;
pub const FIN: u8 = 0x01;
pub const RST: u8 = 0x04;

pub const CLIENT: (Ipv4Addr, u16) = (Ipv4Addr::new(10, 0, 0, 1), 40000);
pub const SERVER: (Ipv4Addr, u16) = (Ipv4Addr::new(10, 0, 0, 2), 8000);

pub struct Frame {
    pub ts_ns: u64,
    pub data: Vec<u8>,
    pub orig_len: u32,
}

fn eth_ipv4(src: Ipv4Addr, dst: Ipv4Addr, proto: u8, l4: &[u8]) -> Vec<u8> {
    let mut p = vec![0x02, 0, 0, 0, 0, 2, 0x02, 0, 0, 0, 0, 1, 0x08, 0x00];
    let total = (20 + l4.len()) as u16;
    p.extend_from_slice(&[0x45, 0]);
    p.extend_from_slice(&total.to_be_bytes());
    p.extend_from_slice(&[0, 0, 0x40, 0, 64, proto, 0, 0]);
    p.extend_from_slice(&src.octets());
    p.extend_from_slice(&dst.octets());
    p.extend_from_slice(l4);
    p
}

pub fn tcp_frame(
    src: (Ipv4Addr, u16),
    dst: (Ipv4Addr, u16),
    seq: u32,
    ack: u32,
    flags: u8,
    payload: &[u8],
) -> Vec<u8> {
    let mut l4 = Vec::with_capacity(20 + payload.len());
    l4.extend_from_slice(&src.1.to_be_bytes());
    l4.extend_from_slice(&dst.1.to_be_bytes());
    l4.extend_from_slice(&seq.to_be_bytes());
    l4.extend_from_slice(&ack.to_be_bytes());
    l4.extend_from_slice(&[0x50, flags, 0xff, 0xff, 0, 0, 0, 0]);
    l4.extend_from_slice(payload);
    eth_ipv4(src.0, dst.0, 6, &l4)
}

pub fn udp_frame(src: (Ipv4Addr, u16), dst: (Ipv4Addr, u16), payload: &[u8]) -> Vec<u8> {
    let mut l4 = Vec::with_capacity(8 + payload.len());
    l4.extend_from_slice(&src.1.to_be_bytes());
    l4.extend_from_slice(&dst.1.to_be_bytes());
    l4.extend_from_slice(&((8 + payload.len()) as u16).to_be_bytes());
    l4.extend_from_slice(&[0, 0]);
    l4.extend_from_slice(payload);
    eth_ipv4(src.0, dst.0, 17, &l4)
}

/// A TCP connection between two endpoints that tracks sequence numbers.
pub struct Conn {
    pub a: (Ipv4Addr, u16),
    pub b: (Ipv4Addr, u16),
    /// Next sequence number from a / from b.
    pub seq_a: u32,
    pub seq_b: u32,
}

impl Conn {
    pub fn new(a: (Ipv4Addr, u16), b: (Ipv4Addr, u16), isn_a: u32, isn_b: u32) -> Self {
        Conn {
            a,
            b,
            seq_a: isn_a,
            seq_b: isn_b,
        }
    }

    /// SYN, SYN-ACK, ACK at `ts`, `ts+1ms`, `ts+2ms`.
    pub fn handshake(&mut self, ts: u64, out: &mut Vec<Frame>) {
        out.push(frame(ts, tcp_frame(self.a, self.b, self.seq_a, 0, SYN, b"")));
        self.seq_a = self.seq_a.wrapping_add(1);
        out.push(frame(
            ts + MS,
            tcp_frame(self.b, self.a, self.seq_b, self.seq_a, SYN | ACK, b""),
        ));
        self.seq_b = self.seq_b.wrapping_add(1);
        out.push(frame(
            ts + 2 * MS,
            tcp_frame(self.a, self.b, self.seq_a, self.seq_b, ACK, b""),
        ));
    }

    /// Data from a (`from_a`) or b, advancing that side's sequence number.
    pub fn send(&mut self, from_a: bool, ts: u64, flags: u8, payload: &[u8]) -> Frame {
        let f = if from_a {
            let f = tcp_frame(self.a, self.b, self.seq_a, self.seq_b, flags, payload);
            self.seq_a = self
                .seq_a
                .wrapping_add(payload.len() as u32 + u32::from(flags & FIN != 0));
            f
        } else {
            let f = tcp_frame(self.b, self.a, self.seq_b, self.seq_a, flags, payload);
            self.seq_b = self
                .seq_b
                .wrapping_add(payload.len() as u32 + u32::from(flags & FIN != 0));
            f
        };
        frame(ts, f)
    }

    /// A pure ACK from a or b.
    pub fn ack(&self, from_a: bool, ts: u64) -> Frame {
        let f = if from_a {
            tcp_frame(self.a, self.b, self.seq_a, self.seq_b, ACK, b"")
        } else {
            tcp_frame(self.b, self.a, self.seq_b, self.seq_a, ACK, b"")
        };
        frame(ts, f)
    }

    /// FIN from a, FIN-ACK from b, final ACK from a.
    pub fn close(&mut self, ts: u64, out: &mut Vec<Frame>) {
        out.push(self.send(true, ts, FIN | ACK, b""));
        out.push(self.send(false, ts + MS, FIN | ACK, b""));
        out.push(self.ack(true, ts + 2 * MS));
    }
}

pub fn frame(ts_ns: u64, data: Vec<u8>) -> Frame {
    let orig_len = data.len() as u32;
    Frame {
        ts_ns,
        data,
        orig_len,
    }
}

/// Cuts a frame to `cap` captured bytes, keeping its original length.
pub fn truncate(mut f: Frame, cap: usize) -> Frame {
    f.data.truncate(cap);
    f
}

/// Writes frames as pcapng with one Ethernet interface named `tap0` and
/// nanosecond timestamps.
pub fn pcapng(frames: &[Frame]) -> Vec<u8> {
    let mut w = PcapNgWriter::new(Vec::new()).expect("writer");
    w.write_pcapng_block(InterfaceDescriptionBlock {
        linktype: DataLink::ETHERNET,
        snaplen: 0,
        options: vec![
            InterfaceDescriptionOption::IfName(Cow::Borrowed("tap0")),
            InterfaceDescriptionOption::IfTsResol(9),
        ],
    })
    .expect("idb");
    for f in frames {
        w.write_pcapng_block(EnhancedPacketBlock {
            interface_id: 0,
            timestamp: Duration::from_nanos(f.ts_ns),
            original_len: f.orig_len,
            data: Cow::Borrowed(&f.data),
            options: vec![],
        })
        .expect("epb");
    }
    w.into_inner()
}

pub struct Fixture {
    pub name: &'static str,
    /// Files in read order: (file name, frames).
    pub files: Vec<(&'static str, Vec<Frame>)>,
}

pub const HTTP_REQUEST: &[u8] = b"GET /v1/models HTTP/1.1\r\nHost: 10.0.0.2:8000\r\n\r\n";
pub const HTTP_RESPONSE_1: &[u8] =
    b"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: 27\r\n\r\n";
pub const HTTP_RESPONSE_2: &[u8] = b"{\"object\":\"list\",\"data\":[]}";

/// One HTTP exchange whose response straddles a window boundary and the
/// boundary between two files.
pub fn span_windows() -> Fixture {
    let mut c = Conn::new(CLIENT, SERVER, 1000, 5000);
    let mut f1 = Vec::new();
    c.handshake(T0 + 100 * MS, &mut f1);
    f1.push(c.send(true, T0 + 200 * MS, PSH | ACK, HTTP_REQUEST));
    f1.push(c.ack(false, T0 + 201 * MS));
    f1.push(c.send(false, T0 + 900 * MS, PSH | ACK, HTTP_RESPONSE_1));
    let mut f2 = Vec::new();
    f2.push(c.ack(true, T0 + 901 * MS));
    f2.push(c.send(false, T0 + 1100 * MS, PSH | ACK, HTTP_RESPONSE_2));
    f2.push(c.ack(true, T0 + 1101 * MS));
    c.close(T0 + 1200 * MS, &mut f2);
    Fixture {
        name: "span_windows",
        files: vec![("span_windows-1.pcapng", f1), ("span_windows-2.pcapng", f2)],
    }
}

pub const MID_OLD: &[u8] = b"data: {\"choices\":[{\"delta\":{\"content\":\"Hel\"}}]}\n\n";
pub const MID_1: &[u8] = b"data: {\"choices\":[{\"delta\":{\"content\":\"lo\"}}]}\n\n";
pub const MID_2: &[u8] = b"data: [DONE]\n\n";

/// A keep-alive Flow first seen mid-stream, with no handshake: the server
/// is sending an SSE response. One late retransmit lies partly before the
/// first byte seen.
pub fn mid_stream() -> Fixture {
    // The server already sent MID_OLD before the capture began.
    let server_seq = 70_000u32;
    let mut c = Conn::new(CLIENT, SERVER, 9_000, server_seq + MID_OLD.len() as u32);
    let mut f = Vec::new();
    f.push(c.send(false, T0 + 10 * MS, PSH | ACK, MID_1));
    f.push(c.ack(true, T0 + 11 * MS));
    // Retransmit of the tail of MID_OLD plus MID_1 (same bytes).
    let mut late = MID_OLD[MID_OLD.len() - 4..].to_vec();
    late.extend_from_slice(MID_1);
    f.push(frame(
        T0 + 12 * MS,
        tcp_frame(
            SERVER,
            CLIENT,
            server_seq + MID_OLD.len() as u32 - 4,
            c.seq_a,
            PSH | ACK,
            &late,
        ),
    ));
    f.push(c.send(false, T0 + 20 * MS, PSH | ACK, MID_2));
    f.push(c.ack(true, T0 + 21 * MS));
    Fixture {
        name: "mid_stream",
        files: vec![("mid_stream.pcapng", f)],
    }
}

pub const LOST_A: &[u8] = b"POST /v1/chat/completions HTTP/1.1\r\n";
pub const LOST_B: &[u8] = b"Content-Type: application/json\r\n";
pub const LOST_C: &[u8] = b"Content-Length: 2\r\n\r\n{}";

/// Three request segments; the Tap misses the middle one, and the server's
/// ACK proves it was sent.
pub fn lost_segment() -> Fixture {
    let mut c = Conn::new(CLIENT, SERVER, 0xffff_ffd0, 7000);
    let mut f = Vec::new();
    c.handshake(T0 + 10 * MS, &mut f);
    f.push(c.send(true, T0 + 20 * MS, ACK, LOST_A));
    let _lost = c.send(true, T0 + 21 * MS, ACK, LOST_B);
    f.push(c.send(true, T0 + 22 * MS, PSH | ACK, LOST_C));
    f.push(c.ack(false, T0 + 23 * MS));
    c.close(T0 + 30 * MS, &mut f);
    Fixture {
        name: "lost_segment",
        files: vec![("lost_segment.pcapng", f)],
    }
}

/// A retransmit that repeats the bytes, one that changes them after
/// delivery, and an out-of-order copy that changes bytes still pending.
pub fn retransmit_differs() -> Fixture {
    let mut c = Conn::new(CLIENT, SERVER, 100, 200);
    let mut f = Vec::new();
    c.handshake(T0 + 10 * MS, &mut f);
    let seq0 = c.seq_a;
    f.push(c.send(true, T0 + 20 * MS, PSH | ACK, b"hello world\n"));
    // Same bytes again: counted, not flagged.
    f.push(frame(
        T0 + 21 * MS,
        tcp_frame(CLIENT, SERVER, seq0, c.seq_b, PSH | ACK, b"hello world\n"),
    ));
    // Different bytes for an already delivered range: flagged at 6..11.
    f.push(frame(
        T0 + 22 * MS,
        tcp_frame(CLIENT, SERVER, seq0, c.seq_b, PSH | ACK, b"hello WORLD\n"),
    ));
    f.push(c.ack(false, T0 + 23 * MS));
    // Out of order: second part first, then a differing copy of it while it
    // is still waiting, then the first part fills the hole.
    let seq1 = c.seq_a;
    let part1 = b"second line ";
    let part2 = b"third line\n";
    let seq2 = seq1 + part1.len() as u32;
    f.push(frame(
        T0 + 30 * MS,
        tcp_frame(CLIENT, SERVER, seq2, c.seq_b, PSH | ACK, part2),
    ));
    f.push(frame(
        T0 + 31 * MS,
        tcp_frame(CLIENT, SERVER, seq2, c.seq_b, PSH | ACK, b"thirD line\n"),
    ));
    f.push(frame(
        T0 + 32 * MS,
        tcp_frame(CLIENT, SERVER, seq1, c.seq_b, ACK, part1),
    ));
    c.seq_a = seq2 + part2.len() as u32;
    f.push(c.ack(false, T0 + 33 * MS));
    c.close(T0 + 40 * MS, &mut f);
    Fixture {
        name: "retransmit_differs",
        files: vec![("retransmit_differs.pcapng", f)],
    }
}

pub const DNS: (Ipv4Addr, u16) = (Ipv4Addr::new(10, 0, 0, 53), 53);

/// UDP datagrams: a query and answer, a truncated answer, a second
/// exchange on the same tuple after the idle timeout (a new Flow
/// generation), and an ARP frame that is not IP.
pub fn udp() -> Fixture {
    let q = b"\x12\x34\x01\x00\x00\x01\x00\x00\x00\x00\x00\x00\x03api\x07example\x00\x00\x01\x00\x01";
    let a = b"\x12\x34\x81\x80\x00\x01\x00\x01\x00\x00\x00\x00\x03api\x07example\x00\x00\x01\x00\x01\xc0\x0c\x00\x01\x00\x01\x00\x00\x00\x3c\x00\x04\x0a\x00\x00\x02";
    let client = (CLIENT.0, 5353);
    let mut f = Vec::new();
    f.push(frame(T0 + 10 * MS, udp_frame(client, DNS, q)));
    f.push(frame(T0 + 11 * MS, udp_frame(DNS, client, a)));
    f.push(truncate(frame(T0 + 12 * MS, udp_frame(DNS, client, a)), 50));
    let mut arp = vec![0xff; 6];
    arp.extend_from_slice(&[0x02, 0, 0, 0, 0, 1, 0x08, 0x06]);
    arp.extend_from_slice(&[0, 1, 8, 0, 6, 4, 0, 1]);
    arp.extend_from_slice(&[0; 20]);
    f.push(frame(T0 + 13 * MS, arp));
    // 61 s later: past the 60 s UDP idle timeout.
    f.push(frame(T0 + 61_100 * MS, udp_frame(client, DNS, q)));
    f.push(frame(T0 + 61_101 * MS, udp_frame(DNS, client, a)));
    Fixture {
        name: "udp",
        files: vec![("udp.pcapng", f)],
    }
}

pub const REDIS_PING: &[u8] = b"*1\r\n$4\r\nPING\r\n";
pub const REDIS_PONG: &[u8] = b"+PONG\r\n";

/// A non-HTTP TCP protocol (Redis), closed with FIN; then the tuple is
/// reused by a new connection (a new SYN), which ends with a RST. One
/// segment is cut by the snap length.
pub fn non_http_tcp() -> Fixture {
    let redis = (SERVER.0, 6379);
    let mut f = Vec::new();
    let mut c = Conn::new(CLIENT, redis, 10, 20);
    c.handshake(T0 + 10 * MS, &mut f);
    f.push(c.send(true, T0 + 20 * MS, PSH | ACK, REDIS_PING));
    f.push(c.send(false, T0 + 21 * MS, PSH | ACK, REDIS_PONG));
    c.close(T0 + 30 * MS, &mut f);

    let mut c = Conn::new(CLIENT, redis, 900_000, 800_000);
    c.handshake(T0 + 100 * MS, &mut f);
    let set = b"*3\r\n$3\r\nSET\r\n$1\r\nk\r\n$32\r\n0123456789abcdef0123456789abcdef\r\n";
    // 54 bytes of headers + 20 bytes of payload captured.
    let cut = c.send(true, T0 + 110 * MS, PSH | ACK, set);
    f.push(truncate(cut, 74));
    f.push(c.send(false, T0 + 111 * MS, PSH | ACK, b"+OK\r\n"));
    f.push(c.send(true, T0 + 120 * MS, RST | ACK, b""));
    Fixture {
        name: "non_http_tcp",
        files: vec![("non_http_tcp.pcapng", f)],
    }
}

pub const EDGE_A_REQ: &[u8] = b"POST /v1/chat/completions HTTP/1.1\r\nHost: gw\r\nContent-Type: application/json\r\nContent-Length: 27\r\n\r\n{\"model\":\"m\",\"stream\":true}";
pub const EDGE_A_RESP: &[u8] =
    b"HTTP/1.1 400 Bad Request\r\nContent-Type: application/json\r\nContent-Length: 15\r\n\r\n{\"error\":\"bad\"}";
pub const EDGE_B_REQ: &[u8] =
    b"POST /v1/completions HTTP/1.1\r\nHost: gw\r\nContent-Length: 13\r\n\r\n{\"model\":\"m\"}";
pub const EDGE_C_REQ: &[u8] = b"GET /metrics HTTP/1.1\r\nHost: gw\r\n\r\n";
pub const EDGE_B_RESP: &[u8] =
    b"HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: 9\r\n\r\ndata: x\n\n";
pub const EDGE_C_HEAD: &[u8] =
    b"HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nTransfer-Encoding: chunked\r\n\r\n";
pub const EDGE_C_CHUNK: &[u8] = b"0123456789abcdefghij";

/// HTTP/1.1 edge cases on one keep-alive Flow:
/// - a streaming chat request in window 0 whose JSON error response comes in
///   window 1: a Workunit (`application/json` is accepted even with
///   `stream: true`), so window 0's request bytes wait for it;
/// - two pipelined requests in one segment;
/// - a non-streaming completion answered with `text/event-stream`: not a
///   Workunit;
/// - a chunked `/metrics` response whose middle segment, inside chunk data,
///   is lost: a gap that keeps the parser in sync.
pub fn http1_edge() -> Fixture {
    let mut c = Conn::new(CLIENT, SERVER, 3000, 4000);
    let mut f = Vec::new();
    c.handshake(T0 + 100 * MS, &mut f);
    f.push(c.send(true, T0 + 200 * MS, PSH | ACK, EDGE_A_REQ));
    f.push(c.ack(false, T0 + 201 * MS));
    f.push(c.send(false, T0 + 1100 * MS, PSH | ACK, EDGE_A_RESP));
    f.push(c.send(
        true,
        T0 + 1200 * MS,
        PSH | ACK,
        &[EDGE_B_REQ, EDGE_C_REQ].concat(),
    ));
    f.push(c.send(false, T0 + 1300 * MS, PSH | ACK, EDGE_B_RESP));
    let first = [EDGE_C_HEAD, b"14\r\n", &EDGE_C_CHUNK[..5]].concat();
    f.push(c.send(false, T0 + 1310 * MS, ACK, &first));
    let _lost = c.send(false, T0 + 1311 * MS, ACK, &EDGE_C_CHUNK[5..15]);
    let last = [&EDGE_C_CHUNK[15..], b"\r\n0\r\n\r\n"].concat();
    f.push(c.send(false, T0 + 1312 * MS, PSH | ACK, &last));
    f.push(c.ack(true, T0 + 1313 * MS));
    c.close(T0 + 1400 * MS, &mut f);
    Fixture {
        name: "http1_edge",
        files: vec![("http1_edge.pcapng", f)],
    }
}

pub const TLS_CLIENT_HELLO: &[u8] = b"\x16\x03\x01\x00\x2f\x01\x00\x00\x2b\x03\x03\
    \x00\x01\x02\x03\x04\x05\x06\x07\x08\x09\x0a\x0b\x0c\x0d\x0e\x0f\
    \x10\x11\x12\x13\x14\x15\x16\x17\x18\x19\x1a\x1b\x1c\x1d\x1e\x1f\
    \x00\x00\x02\x13\x01\x01\x00\x00\x00";
pub const TLS_SERVER_HELLO: &[u8] = b"\x16\x03\x03\x00\x0a\x02\x00\x00\x06\x03\x03\x00\x13\x01\x00";
pub const TLS_APP_DATA: &[u8] = b"\x17\x03\x03\x00\x05\xde\xad\xbe\xef\x00";

/// A TLS handshake and one application-data record on port 8000 of the
/// plaintext Link: verdict `tls`, every byte unexplained.
pub fn tls_plaintext() -> Fixture {
    let mut c = Conn::new(CLIENT, SERVER, 500, 600);
    let mut f = Vec::new();
    c.handshake(T0 + 10 * MS, &mut f);
    f.push(c.send(true, T0 + 20 * MS, PSH | ACK, TLS_CLIENT_HELLO));
    f.push(c.send(false, T0 + 21 * MS, PSH | ACK, TLS_SERVER_HELLO));
    f.push(c.send(true, T0 + 22 * MS, PSH | ACK, TLS_APP_DATA));
    c.close(T0 + 30 * MS, &mut f);
    Fixture {
        name: "tls_plaintext",
        files: vec![("tls_plaintext.pcapng", f)],
    }
}

pub const H2_PREFACE: &[u8] = b"PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n";

pub fn h2_frame(ty: u8, flags: u8, stream: u32, payload: &[u8]) -> Vec<u8> {
    let mut f = (payload.len() as u32).to_be_bytes()[1..].to_vec();
    f.push(ty);
    f.push(flags);
    f.extend_from_slice(&stream.to_be_bytes());
    f.extend_from_slice(payload);
    f
}

/// HPACK header block of literals without indexing, new names, no Huffman.
pub fn hpack_literals(fields: &[(&str, &str)]) -> Vec<u8> {
    let mut b = Vec::new();
    for (n, v) in fields {
        b.extend_from_slice(&[0x00, n.len() as u8]);
        b.extend_from_slice(n.as_bytes());
        b.push(v.len() as u8);
        b.extend_from_slice(v.as_bytes());
    }
    b
}

/// A gRPC call over h2c: parsed as HTTP/2, verdict `grpc`, payload opaque.
pub fn grpc_h2c() -> Fixture {
    const HEADERS: u8 = 1;
    const DATA: u8 = 0;
    const SETTINGS: u8 = 4;
    let mut c = Conn::new(CLIENT, (SERVER.0, 50051), 7000, 8000);
    let mut f = Vec::new();
    c.handshake(T0 + 10 * MS, &mut f);
    let req_head = hpack_literals(&[
        (":method", "POST"),
        (":scheme", "http"),
        (":path", "/pkg.Svc/Call"),
        ("content-type", "application/grpc"),
    ]);
    let client = [
        H2_PREFACE,
        &h2_frame(SETTINGS, 0, 0, b""),
        &h2_frame(HEADERS, 0x4, 1, &req_head),
        &h2_frame(DATA, 0x1, 1, b"\x00\x00\x00\x00\x03abc"),
    ]
    .concat();
    f.push(c.send(true, T0 + 20 * MS, PSH | ACK, &client));
    let resp_head = hpack_literals(&[(":status", "200"), ("content-type", "application/grpc")]);
    let server = [
        &h2_frame(SETTINGS, 0, 0, b"")[..],
        &h2_frame(SETTINGS, 0x1, 0, b""),
        &h2_frame(HEADERS, 0x4, 1, &resp_head),
        &h2_frame(DATA, 0, 1, b"\x00\x00\x00\x00\x02ok"),
        &h2_frame(HEADERS, 0x5, 1, &hpack_literals(&[("grpc-status", "0")])),
    ]
    .concat();
    f.push(c.send(false, T0 + 21 * MS, PSH | ACK, &server));
    c.close(T0 + 30 * MS, &mut f);
    Fixture {
        name: "grpc_h2c",
        files: vec![("grpc_h2c.pcapng", f)],
    }
}

pub fn all() -> Vec<Fixture> {
    vec![
        span_windows(),
        mid_stream(),
        lost_segment(),
        retransmit_differs(),
        udp(),
        non_http_tcp(),
        http1_edge(),
        tls_plaintext(),
        grpc_h2c(),
    ]
}

/// Real traffic from `fixtures/capture/capture.py`: the OpenAI SDK against
/// the mock server, captured with dumpcap on `lo`.
pub const CAPTURED: &[&str] = &[
    "openai_h1_json",
    "openai_h1_sse",
    "openai_h2c_json",
    "openai_h2c_sse",
    "http_other_h1",
    "openai_responses_h1_json",
    "openai_responses_h1_sse",
    "openai_responses_h2c_json",
    "openai_responses_h2c_sse",
    "openai_responses_error_h1",
];

pub const DUMPCAP_KEEPALIVE: &[&str] = &[
    "dumpcap_keepalive-1.pcapng",
    "dumpcap_keepalive-2.pcapng",
    "dumpcap_keepalive-3.pcapng",
    "dumpcap_keepalive-4.pcapng",
    "dumpcap_keepalive-5.pcapng",
];

/// Every golden case: (case name, files in read order).
pub fn cases() -> Vec<(String, Vec<String>)> {
    let mut cases: Vec<(String, Vec<String>)> = all()
        .into_iter()
        .map(|fx| {
            (
                fx.name.to_string(),
                fx.files.iter().map(|(n, _)| n.to_string()).collect(),
            )
        })
        .collect();
    cases.push((
        "dumpcap_keepalive".into(),
        DUMPCAP_KEEPALIVE.iter().map(|s| s.to_string()).collect(),
    ));
    for name in CAPTURED {
        cases.push((name.to_string(), vec![format!("{name}.pcapng")]));
    }
    cases
}
